function isPalindrome(s) {
  let i = 0, j = s.length - 1; const ok = c => /[A-Za-z0-9]/.test(c);
  while (i < j) {
    if (!ok(s[i])) { i++; continue; } if (!ok(s[j])) { j--; continue; }
    if (s[i].toLowerCase() !== s[j].toLowerCase()) return false; i++; j--;
  }
  return true;
}
